def affected(l) -> bool:
    # Mutant keeps x > -1 instead of x > 0. The two predicates differ only
    # for values in (-1, 0]. If any comparison raises, both versions raise
    # on the same element (same comparison types), so the result is unchanged.
    try:
        diff = False
        for x in l:
            if (x > -1) != (x > 0):
                diff = True
        return diff
    except Exception:
        return False
